import json
def add_v16(d,P,new_page,para,table,picture,link,is_glasses):
 O=P/'engineering-v16-results';f=O/'selected_candidates.json'
 if not f.exists():return
 selected=json.loads(f.read_text());new_page(d,'V16 Indexed folding and rivet retention')
 para(d,'Project status: V16 indexed folding candidates with V10 native archives.')
 para(d,'V16 adds holes for the wearing and folded positions. The locking pins can return into the folded holes instead of staying held back. A recessed cross rivet retains each knob on its stem. This is an alternative to the longer V15 threaded knob and jam nut. It keeps the earlier 8 mm knob envelope, but servicing the pin means removing the rivet.')
 para(d,'The selected child plate is a lower half disc with 16 mm radius and 3 mm thickness. Adult cups collided with this lower plate. The adult alternative puts a trimmed upper plate behind the guide and relocates the release housing. The child and adult fork arrangements differ and need their own strength checks.')
 if (P/'documents/images/V16_sections.png').exists():picture(d,'V16_sections','Actual sections of saved V16 wear-position geometry. Colours identify parts, not selected materials. A final formed rivet is drawn; the upsetting process and spring friction are not modelled.',6.2)
 para(d,'The rivet shaft is 0.8 mm across, in a nominal 0.85 mm cross hole. Its formed heads are 1.2 mm across and sit in recesses. The knob bore is 2.3 mm around the 2.2 mm stem. These dimensions define positive geometric capture. Actual tolerances, metal grade, riveting tools, forming strain, wear and proof loads remain unqualified.')
 new_page(d,'V16 Recorded checks and packing')
 rows=[]
 for r in selected['sizes']:
  a=json.loads((O/(r['variant']+'_audit.json')).read_text());p=a['packing'];rows.append([r['size'].replace('_',' '),str(a['case_count']),f"{p['reduction_from_retracted_percent']:.2f} percent smaller"])
 table(d,['Size','Sampled sequence checks','Folded box against retracted unfolded'],rows,[1.6,1.9,3.4])
 para(d,f"The six selected candidates have {selected['motion_sample_count']} recorded sequence samples, {selected['solid_validity_checks']} solid-validity checks, {selected['index_blocking_queries']} pin blocking queries and {selected['retention_blocking_queries']} rivet capture queries. The new plate query controls also use known embedded, disjoint and rotated test cubes. These are geometric checks, not force or durability results.")
 para(d,'The sequences include slider movement, release, folding and pin return at the folded holes. At the indexed positions, an attempted one degree rotation produces pin to plate interference. Attempted rivet escape and knob withdrawal also produce interference. That supports the intended mechanical capture in rigid CAD. It does not measure holding force or prove that a spring reliably seats a real pin.')
 exports=O/'STEP_verification.json'
 if exports.exists():
  e=json.loads(exports.read_text());para(d,f"The {e['case_count']} selected wear, released and folded engaged STEP exports "+('passed' if e['all_pass'] else 'include failures in')+' independent reimport checks for solid count, validity and volume. Folded boxes were also compared with the audited poses. Native editable Fusion archives remain V10; V16 is local STEP work.')
 if not is_glasses and (P/'documents/images/V16_folded_CAD.png').exists():
  new_page(d,'V16 Retracted and folded CAD')
  picture(d,'V16_folded_CAD','Actual selected child large and adult small surfaces with the checked rigid folding transforms. Equal scale within each row. Pins are geometrically engaged in the folded holes.',6.2)
 para(d,'The packing figures compare a folded box with the same headset fully retracted and unfolded. They are not bag-fit or travel tests. V16 removes the held-release requirement in the checked geometry, but real spring return, finger clearance, stops outside the indexed positions and voluntary handling still need work.')
 if not is_glasses:
  new_page(d,'V16 Component and material calculations')
  fe=O/'tongue_mechanics_summary.json'
  if fe.exists():
   s=json.loads(fe.read_text());last=s['meshes'][-1];table(d,['Fixture','Fine displacement mm','Fine sampled stress MPa','Mesh comparison'],[['Child large lower plate',f"{last['weighted_load_direction_displacement_mm']:.4f}",f"{last['max_von_mises_centroid_MPa']:.2f}",'Pass' if s['mesh_comparison_pass'] else 'Fail']],[1.8,1.6,1.7,1.8])
   para(d,f"The two final meshes change displacement by {100*s['displacement_mesh_change_fraction']:.2f} percent and sampled peak stress by {100*s['sampled_peak_stress_mesh_change_fraction']:.2f} percent. The chosen comparison limit is 5 percent. The saved-array algebra audit "+('passed.' if s['algebra_audits_pass'] else 'did not pass.'))
   para(d,'This child large fixture truncates the stem at the guide entrance at z 82 mm and fixes that section as an ideal rigid support. It spreads an illustrative 11.63 N tangential load over the folded hole and assumes modulus 2000 MPa and Poisson ratio 0.35. Actual guide gaps, pin bearing pressure, screw preload, friction, cap fasteners and whole joint contact are excluded. It does not qualify the different adult upper plate and support.')
   top=s['alternative_top_only_fixture'];para(d,f"A first fixture fixed only the top face at z 134 mm and omitted guide support. It predicted {top['weighted_load_direction_displacement_mm']:.2f} mm movement. That is too much bending to treat its small-displacement solution as a reliable product prediction. Its finer solve was interrupted and is not a refinement pass. The ideal guide fixture gives {last['weighted_load_direction_displacement_mm']:.3f} mm. These different assumptions show why actual support and contact must be resolved; they are not guaranteed bounds on the real headset.")
   adult=s.get('adult_upper_fixture')
   if adult:
    r=adult['meshes'][-1];table(d,['Separate adult fixture','Displacement mm','Sampled stress MPa'],[['Adult small upper plate and neck',f"{r['weighted_load_direction_displacement_mm']:.4f}",f"{r['max_von_mises_centroid_MPa']:.2f}"]],[2.9,2.0,2.0])
    para(d,f"The adult small comparison changes displacement by {100*adult['displacement_mesh_change_fraction']:.2f} percent and sampled stress by {100*adult['sampled_peak_stress_mesh_change_fraction']:.2f} percent. Both meet the chosen 5 percent comparison, and the saved-array algebra audits pass. The assumed load is 10.83 N, with the same ideal z 82 support and assumed elastic material. This checks only the tongue and neck, not the relocated fork or complete joint.")
    para(d,'Two curved high-order mesh attempts failed and are retained. The accepted adult calculations use straight-sided quadratic tetrahedra, so curved boundaries are approximated with facets. Mesh comparison does not remove that approximation or establish a product strength rating.')
  para(d,'The first adult lower plate collided with both cup shells and liners. The first relocated housing also had its new support arm fill part of the pin and spring space. Both failures are retained. A corrected housing restores those clearances. One initial upper-plate query cube crossed an index hole, so its location was corrected before using that control. These corrections are not erased by the later passes.')
 material=json.loads((O/'materials_reference_screen.json').read_text())
 para(d,'Material selection still needs actual grades and samples. A BASF PA6 reference lists modulus 3500 MPa dry and 1200 MPa conditioned, with yield references 90 and 45 MPa. That is a large condition effect to account for in India; it is not a prediction for our exact weather or manufactured parts. A previously recorded POM reference is included for comparison.')
 link(d,'BASF Ultramid B3S product data',material['grade_references'][0]['source'])
 para(d,'The new screen records 45 nominal plate-load cases and 15 cross-drilled stem pull cases. The plate calculation uses bearing and a minimum-ligament proxy with chosen peak multipliers. The stem calculation uses its central remaining area and an assumed multiplier. Neither is a complete joint stress model or a qualified material rating.')
 if not is_glasses:new_page(d,'V16 Cushion data and physical test records')
 para(d,'Two published thin PORON battery-pad curves add more compression information than a single stiffness number. Only 12 of 36 assumed flat-area load cases fall within their published 20 to 70 percent strain range. We leave the other 24 without a predicted strain. These 0.85 to 3 mm grades cannot establish the behaviour of our shaped 20 mm cushion, cover, glasses seal or wearer comfort.')
 link(d,'Rogers published compression curves',material['foam_source'])
 if (P/'documents/images/V16_foam_reference.png').exists():picture(d,'V16_foam_reference','Manufacturer reference data for thin sheets. No low-pressure extrapolation or manufactured headphone result is claimed.',5.8)
 para(d,'Seven blank CSV record templates are prepared for Sony measurements, foam and cover calibration, band and joint measurements, acoustic comparisons, wearer feedback, durability and supplier quotes. Their result cells are empty. The geometry quote BOM lists net CAD volumes and flags spring spaces as allocations that must not be priced or weighed as solid parts.')
 para(d,'Draft durability screens include 5000 folding and slider cycles, 1 m drops in six orientations and 24 hours at 45 C and 85 percent relative humidity. These are proposed engineering targets to review before testing, not a standard, a completed test or a service-life claim. Real samples and instruments are still required.')
 para(d,'Acoustic work must compare original and candidate seating with the same fixture and glasses frames. Incoming noise and outgoing playback are separate tests. For outgoing music, match measured internal playback level before comparing external sound and report uncertainty. No leakage or ANC benefit is established by CAD.')
 if is_glasses:para(d,'The Sony WH CH720N cushion geometry is unchanged. The user deferred its mounting measurements. The new standalone mechanisms do not qualify Sony fit, seal, pressure, frequency response or ANC behaviour. These remain separate entries in the shared test records.')
 para(d,'No physical test has been performed in this update. Comfort and sensory acceptance require voluntary wearer feedback. Production cost requires real quotes including forming, tooling, assembly, inspection, scrap, packaging and distribution. The product remains a prototype candidate, with complete joint strength, actual materials, manufacturing tolerances and physical validation unfinished.')
 tolerance=O/'joint_tolerance_screen.json'
 if tolerance.exists():
  t=json.loads(tolerance.read_text());v=json.loads((O/'offset_contact_validation.json').read_text())
  new_page(d,'V16 Joint clearance and manufacturing errors')
  para(d,'The 2.3 mm index hole and 2.2 mm pin leave only 0.05 mm of radial clearance. A nominal geometry pass is therefore not enough to establish reliable assembly or spring return. Both documents now record this manufacturing constraint; the CAD has not changed in this update.')
  table(d,['Interface','Nominal radial clearance mm'],[['Index hole and pin','0.050'],['Cross drill and rivet shaft','0.025'],['Knob bore and stem','0.050'],['Rivet head recess and head','0.050']],[4.4,2.5])
  para(d,f"The bounded-error screen records {t['case_count']} index scenarios across six sizes and {t['interface_case_count']} other interface scenarios. Only {t['positive_margin_cases']} index scenarios retain a positive worst-case clearance. These are deliberately chosen error combinations, not random samples, supplier capabilities or a predicted factory yield. Losing a worst-case guarantee does not mean every real part fails.")
  para(d,f"A separate check on the saved solids ran {v['case_count']} pin-to-plate offset queries. At both sides of all six sizes, 0.04 mm sideways offset stays clear and 0.06 mm produces interference, agreeing with the nominal radial clearance calculation. This checks only the wearing-position pin and tongue; it excludes the guide, cap, spring and actual manufactured surfaces.")
  picture(d,'V16_joint_tolerances','Calculated clearance budget with no centre error. The zero line includes contact and interference; it is not a measured performance curve.',5.0 if is_glasses else 5.8)
  para(d,'With no dimensional or alignment error, the index clearance allows about 0.256 degrees of rotation each way for the child plate and 0.239 degrees for the adult plate before contact. This is only the index-hole contribution. Pivot clearance, guide play and elastic movement add their own effects.')
  para(d,'For example, opposite diameter errors of 0.025 mm on both parts reduce the available radial clearance to 0.025 mm. A further 0.025 mm centre error uses all of it, even before angular error, surface roughness or swelling. The rivet cross hole has a smaller starting clearance and needs its own process decision.')
  para(d,'The next mechanism change must balance easier pin entry against rotational looseness. Larger holes, an entry chamfer, a guided or compliant pin and tighter alignment control are candidates to compare. None is selected or qualified here. We still need real manufacturing capability, spring return force, friction, contamination and cycle measurements before approving tolerances.')
  if is_glasses:para(d,'These are standalone defender joint checks. The Sony replacement cushion has no such joint; its mounting measurements and physical seal tests remain outstanding.')
